head.b:skin:
/*
 * EditorialVocab AdSense Pro Theme
 * Clean, Fast, High-Readability Publisher Theme
 * 100% AdSense Policy & Core Web Vitals Compliant
 */

:root {
  --bg-body: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-alt: #f1f5f9;
  --text-main: #0f172a;
  --text-body: #334155;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --border-color: #e2e8f0;
  --border-strong: #cbd5e1;

  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #eef2ff;

  --accent-emerald: #059669;
  --accent-amber: #d97706;
  --accent-rose: #e11d48;

  --font-heading: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-body: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-serif: 'Merriweather', Georgia, serif;
  --font-hindi: 'Hind', sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 14px rgba(0,0,0,0.06);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.08);

  --container-max: 1200px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg-body);
  color: var(--text-body);
  font-family: var(--font-body);
  line-height: 1.7;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--primary-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Layout Structure */
.ev-container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 20px;
  width: 100%;
}

/* Top Announcement Bar */
.ev-topbar {
  background-color: #0f172a;
  color: #e2e8f0;
  font-size: 12.5px;
  padding: 7px 0;
  border-bottom: 1px solid #1e293b;
}

.ev-topbar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.ev-topbar-links {
  display: flex;
  gap: 16px;
  align-items: center;
}

.ev-topbar-links a {
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
}

.ev-topbar-links a:hover {
  color: #ffffff;
  text-decoration: none;
}

/* Site Header */
.ev-header {
  background-color: #ffffff;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.ev-header-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  gap: 20px;
}

.ev-brand {
  display: flex;
  flex-direction: column;
}

.ev-logo-text {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 900;
  color: var(--text-main);
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.ev-logo-text span {
  color: var(--primary);
}

.ev-tagline {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 500;
  margin-top: -2px;
}

/* Navigation Bar */
.ev-nav {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ev-nav-link {
  color: var(--text-body);
  font-size: 14px;
  font-weight: 700;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
  white-space: nowrap;
}

.ev-nav-link:hover, .ev-nav-link.active {
  color: var(--primary);
  background-color: var(--primary-light);
  text-decoration: none;
}

.ev-nav-badge {
  background: var(--accent-rose);
  color: #ffffff;
  font-size: 10px;
  padding: 2px 6px;
  border-radius: var(--radius-full);
  margin-left: 4px;
  font-weight: 800;
}

/* Search Bar in Header */
.ev-search-form {
  position: relative;
  display: flex;
  align-items: center;
}

.ev-search-input {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  padding: 8px 14px 8px 34px;
  border-radius: var(--radius-full);
  font-size: 13px;
  color: var(--text-main);
  outline: none;
  width: 180px;
  transition: all 0.2s ease;
}

.ev-search-input:focus {
  width: 240px;
  border-color: var(--primary);
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.ev-search-icon {
  position: absolute;
  left: 12px;
  color: var(--text-light);
  pointer-events: none;
  font-size: 13px;
}

/* Mobile Menu Toggle */
.ev-mobile-toggle {
  display: none;
  background: none;
  border: 1px solid var(--border-color);
  padding: 8px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 20px;
  color: var(--text-main);
}

/* Ad Units - Clear AdSense Policy Compliant */
.ev-ad-slot {
  margin: 20px auto;
  text-align: center;
  max-width: 100%;
  overflow: hidden;
}

.ev-ad-label {
  display: block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  color: var(--text-light);
  text-transform: uppercase;
  margin-bottom: 6px;
  text-align: center;
}

.ev-ad-box {
  min-height: 90px;
  background: #f8fafc;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto;
  padding: 10px;
}

/* Main Content & Sidebar Grid */
.ev-main-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 32px;
  margin: 32px auto 50px auto;
}

.ev-content-column {
  min-width: 0;
}

.ev-sidebar-column {
  min-width: 0;
}

/* Article Cards List (Homepage / Index) */
.ev-hero-banner {
  background: linear-gradient(135deg, #1e1b4b 0%, #312e81 50%, #0f172a 100%);
  color: #ffffff;
  padding: 32px;
  border-radius: var(--radius-lg);
  margin-bottom: 30px;
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
}

.ev-hero-eyebrow {
  display: inline-block;
  background: rgba(255,255,255,0.15);
  color: #cbd5e1;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  letter-spacing: 1px;
  margin-bottom: 12px;
}

.ev-hero-title {
  font-size: clamp(22px, 3.5vw, 32px);
  font-weight: 900;
  line-height: 1.25;
  margin-bottom: 12px;
  color: #ffffff;
}

.ev-hero-desc {
  font-size: 15px;
  color: #cbd5e1;
  max-width: 680px;
  line-height: 1.6;
  margin-bottom: 20px;
}

.ev-hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.ev-hero-badge {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 12.5px;
  font-weight: 700;
}

.ev-hero-badge:hover {
  background: #ffffff;
  color: #0f172a;
  text-decoration: none;
}

/* Section Headers */
.ev-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 12px;
  margin-bottom: 24px;
}

.ev-section-title {
  font-size: 20px;
  font-weight: 900;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.ev-section-title::before {
  content: '';
  display: block;
  width: 4px;
  height: 20px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

/* Post Feed Cards */
.ev-posts-feed {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.ev-post-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  flex-direction: column;
}

.ev-post-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--border-strong);
}

.ev-card-image {
  width: 100%;
  max-height: 240px;
  object-fit: cover;
  border-bottom: 1px solid var(--border-color);
}

.ev-card-content {
  padding: 22px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.ev-card-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 10px;
  flex-wrap: wrap;
}

.ev-card-source {
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 800;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ev-card-title {
  font-size: 20px;
  font-weight: 800;
  line-height: 1.35;
  color: var(--text-main);
  margin-bottom: 10px;
}

.ev-card-title a {
  color: var(--text-main);
}

.ev-card-title a:hover {
  color: var(--primary);
  text-decoration: none;
}

.ev-card-snippet {
  font-size: 14px;
  color: var(--text-body);
  line-height: 1.6;
  margin-bottom: 16px;
  flex: 1;
}

.ev-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-color);
  padding-top: 14px;
  font-size: 13px;
  font-weight: 700;
}

.ev-read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--primary);
  font-weight: 800;
}

.ev-read-more:hover {
  gap: 10px;
  text-decoration: none;
}

/* Single Post / Item Page Styling */
.ev-article-view {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: clamp(20px, 4vw, 36px);
  box-shadow: var(--shadow-sm);
}

.ev-breadcrumbs {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.ev-breadcrumbs a {
  color: var(--text-muted);
}

.ev-breadcrumbs a:hover {
  color: var(--primary);
}

.ev-article-title {
  font-size: clamp(24px, 4vw, 34px);
  font-weight: 900;
  color: var(--text-main);
  line-height: 1.25;
  margin-bottom: 16px;
}

.ev-article-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 13px;
  color: var(--text-muted);
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.ev-post-body {
  font-size: 16px;
  line-height: 1.75;
  color: var(--text-main);
}

.ev-post-body p {
  margin-bottom: 16px;
}

.ev-post-body h2 {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-main);
  margin: 28px 0 14px 0;
  line-height: 1.3;
}

.ev-post-body h3 {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-main);
  margin: 22px 0 10px 0;
}

.ev-post-body ul, .ev-post-body ol {
  margin: 0 0 18px 24px;
}

.ev-post-body li {
  margin-bottom: 6px;
}

/* Social Share Bar */
.ev-share-bar {
  margin: 32px 0;
  padding: 16px 20px;
  background: var(--bg-card-alt);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.ev-share-title {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-main);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ev-share-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.ev-btn-share {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 700;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  color: #ffffff;
  text-decoration: none;
  transition: opacity 0.2s ease;
}

.ev-btn-share:hover {
  opacity: 0.9;
  text-decoration: none;
  color: #ffffff;
}

.ev-btn-wa { background: #25d366; }
.ev-btn-tg { background: #0088cc; }
.ev-btn-tw { background: #000000; }

/* Static Policy Pages */
.ev-static-page {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: clamp(24px, 4vw, 44px);
  box-shadow: var(--shadow-sm);
}

.ev-static-title {
  font-size: clamp(26px, 4vw, 34px);
  font-weight: 900;
  color: var(--text-main);
  margin-bottom: 20px;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 16px;
}

/* 404 ERROR PAGE STYLES - 100% Comprehensive Handling */
.ev-error-page {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: clamp(32px, 5vw, 60px) 24px;
  text-align: center;
  box-shadow: var(--shadow-md);
  max-width: 800px;
  margin: 30px auto;
}

.ev-error-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: #fee2e2;
  color: #ef4444;
  font-size: 36px;
  margin-bottom: 18px;
}

.ev-error-code {
  font-size: clamp(48px, 8vw, 84px);
  font-weight: 900;
  color: var(--text-main);
  line-height: 1;
  letter-spacing: -2px;
  margin-bottom: 10px;
}

.ev-error-heading {
  font-size: clamp(20px, 3.5vw, 26px);
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 12px;
}

.ev-error-desc {
  font-size: 15px;
  color: var(--text-muted);
  max-width: 540px;
  margin: 0 auto 24px auto;
  line-height: 1.6;
}

.ev-error-search {
  max-width: 460px;
  margin: 0 auto 28px auto;
}

.ev-error-search-box {
  display: flex;
  gap: 8px;
}

.ev-error-search-input {
  flex: 1;
  padding: 12px 18px;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}

.ev-error-search-input:focus {
  border-color: var(--primary);
}

.ev-error-search-btn {
  background: var(--primary);
  color: #ffffff;
  border: none;
  padding: 12px 22px;
  border-radius: var(--radius-md);
  font-weight: 800;
  font-size: 14px;
  cursor: pointer;
}

.ev-error-search-btn:hover {
  background: var(--primary-hover);
}

.ev-error-quick-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-bottom: 24px;
}

.ev-error-btn {
  background: var(--bg-card-alt);
  color: var(--text-main);
  border: 1px solid var(--border-color);
  padding: 10px 18px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 700;
  transition: all 0.2s ease;
}

.ev-error-btn:hover {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
  text-decoration: none;
}

.ev-error-btn-primary {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.ev-error-btn-primary:hover {
  background: var(--primary-hover);
}

/* Sidebar Widgets */
.ev-widget-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
}

.ev-widget-title {
  font-size: 16px;
  font-weight: 900;
  color: var(--text-main);
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 10px;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.ev-widget-title::before {
  content: '';
  display: block;
  width: 4px;
  height: 16px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

/* Label Cloud Widget */
.ev-label-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ev-label-tag {
  background: var(--bg-card-alt);
  border: 1px solid var(--border-color);
  color: var(--text-body);
  font-size: 12.5px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s ease;
}

.ev-label-tag:hover {
  background: var(--primary-light);
  color: var(--primary);
  border-color: var(--primary);
  text-decoration: none;
}

.ev-label-count {
  background: var(--border-strong);
  color: var(--text-main);
  font-size: 10px;
  padding: 2px 6px;
  border-radius: var(--radius-full);
  font-weight: 800;
}

/* About Author Widget */
.ev-author-box {
  text-align: center;
}

.ev-author-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  margin: 0 auto 12px auto;
  border: 3px solid var(--border-color);
}

.ev-author-name {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 4px;
}

.ev-author-bio {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 14px;
}

/* Pagination / Next Prev */
.ev-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 32px 0;
  gap: 12px;
}

.ev-page-btn {
  background: var(--bg-card);
  border: 1.5px solid var(--border-color);
  color: var(--text-main);
  font-size: 14px;
  font-weight: 800;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.ev-page-btn:hover {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
  text-decoration: none;
  box-shadow: var(--shadow-md);
}

/* Footer Styles - AdSense Compliance */
.ev-footer {
  background: #0f172a;
  color: #cbd5e1;
  margin-top: auto;
  border-top: 1px solid #1e293b;
  padding: 50px 0 24px 0;
}

.ev-footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 36px;
  margin-bottom: 40px;
}

.ev-footer-brand {
  font-size: 22px;
  font-weight: 900;
  color: #ffffff;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.ev-footer-brand span {
  color: #818cf8;
}

.ev-footer-desc {
  font-size: 13.5px;
  line-height: 1.6;
  color: #94a3b8;
  margin-bottom: 16px;
  max-width: 320px;
}

.ev-footer-title {
  font-size: 14px;
  font-weight: 800;
  color: #ffffff;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 16px;
  border-bottom: 1px solid #334155;
  padding-bottom: 8px;
}

.ev-footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ev-footer-links a {
  color: #94a3b8;
  font-size: 13.5px;
  font-weight: 600;
  transition: color 0.2s ease;
}

.ev-footer-links a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.ev-footer-bottom {
  border-top: 1px solid #1e293b;
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 12.5px;
  color: #64748b;
}

.ev-footer-policy-row {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.ev-footer-policy-row a {
  color: #94a3b8;
}

.ev-footer-policy-row a:hover {
  color: #ffffff;
}

/* Print Media Styles */
@media print {
  .ev-topbar, .ev-header, .ev-footer, .ev-sidebar-column, .ev-ad-slot,
  .ev-share-bar, .ev-pagination, .ev-breadcrumbs, #comments, .comments,
  #ev-toc-bar, #ev-pdf-section, #ev-quiz-section, #evQBox, .evNav, .evScorecard, button {
    display: none !important;
  }

  body, .ev-main-layout, .ev-content-column {
    background: #ffffff !important;
    color: #0f172a !important;
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
    max-width: 100% !important;
  }

  .ev-article-view {
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
  }

  .ev-post-card, #ev-vocab-section > div, #ev-idioms-section, #ev-idioms-section > div > div, .ev-print-quiz {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
    border: 1px solid #cbd5e1 !important;
    background: #ffffff !important;
    box-shadow: none !important;
    margin-bottom: 14px !important;
  }

  .ev-print-quiz {
    display: block !important;
  }
}

/* Responsive Breakpoints */
@media (max-width: 992px) {
  .ev-main-layout {
    grid-template-columns: 1fr;
  }

  .ev-footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .ev-nav {
    display: none;
  }

  .ev-mobile-toggle {
    display: block;
  }

  .ev-nav.active {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: #ffffff;
    border-bottom: 1px solid var(--border-color);
    padding: 16px 20px;
    box-shadow: var(--shadow-md);
  }
}

@media (max-width: 640px) {
  .ev-footer-grid {
    grid-template-columns: 1fr;
  }

  .ev-topbar-inner {
    justify-content: center;
    text-align: center;
  }

  .ev-topbar-links {
    display: none;
  }

  .ev-header-main {
    flex-wrap: wrap;
  }

  .ev-search-input {
    width: 140px;
  }

  .ev-search-input:focus {
    width: 180px;
  }
}
